import sys
from array import array

def ints_from_bytes(data):
    num = 0
    in_num = False
    for b in data:
        if 48 <= b <= 57:
            num = num * 10 + (b - 48)
            in_num = True
        else:
            if in_num:
                yield num
                num = 0
                in_num = False
    if in_num:
        yield num

def main():
    data = sys.stdin.buffer.read()
    it = ints_from_bytes(data)

    n = next(it)
    arr = array('q', [0]) * n
    for i in range(n):
        arr[i] = next(it)

    i = 0
    j = n - 1
    left = arr[i]
    right = arr[j]
    ops = 0

    while i < j:
        if left == right:
            i += 1
            j -= 1
            if i <= j:
                left = arr[i]
                right = arr[j]
        elif left < right:
            i += 1
            left += arr[i]
            ops += 1
        else:
            j -= 1
            right += arr[j]
            ops += 1

    sys.stdout.write(str(ops))

if __name__ == "__main__":
    main()
